STR_DE[mw2_exec_ok]="[i] Die Datei ist ausführbar (ELF/PE). Stelle sicher, dass du die Quelle kennst, bevor du sie ausführst."
STR_TR[mw2_exec_ok]="[i] Dosya çalıştırılabilir (ELF/PE). Çalıştırmadan önce kaynağını bildiğinizden emin olun."
STR_FA[mw2_exec_ok]="[i] فایل اجرایی است (ELF/PE). قبل از اجرا مطمئن شوید منبع آن را می‌شناسید."
STR_RU[mw2_exec_ok]="[i] Файл исполняемый (ELF/PE). Убедитесь, что вам известен его источник, прежде чем запускать."
STR_KU[mw2_exec_ok]="[i] فایلەکە جێبەجێکراوە (ELF/PE). دڵنیابەرەوە کە سەرچاوەکەی دەزانیت پێش ڕایبگرن."
