STR_TR[mw4_medium_entropy]="[i] Orta-yüksek entropi — dosya sıkıştırılmış veya normal bir ikili dosya olabilir."
STR_FA[mw4_medium_entropy]="[i] آنتروپی متوسط تا بالا — ممکن است فایل فشرده یا باینری معمولی باشد."
STR_RU[mw4_medium_entropy]="[i] Средне-высокая энтропия — файл может быть сжат или являться обычным бинарным файлом."
STR_KU[mw4_medium_entropy]="[i] ئێنترۆپی مامناوەند-بەرز — لەوانەیە فایلەکە پەستراو یان بایناریی ئاسایی بێت."
STR_ZH[mw4_medium_entropy]="[i] 中高熵值 — 文件可能已压缩或为普通二进制文件。"

