STR_AR[mw4_windowed_title]="تحليل الإنتروبيا حسب نوافذ متحركة (لكشف كتلة محزومة/مشفرة مضمّنة داخل ملف طبيعي):"
STR_EN[mw4_windowed_title]="Sliding-window entropy scan (detects a packed/encrypted blob embedded inside an otherwise normal file):"

