STR_ZH[mw7_title]="🧹 自动扫描并清除常见恶意软件与恶意注入"

STR_AR[mw7_warning]="أداة استدلالية (heuristic) تعتمد على أنماط شائعة لصدفات الويب وأبواب الثبات الخلفية — راجع كل نتيجة قبل الحذف، ولا تُغني عن برنامج مكافحة فيروسات متخصص."
STR_EN[mw7_warning]="Heuristic tool based on common patterns for web shells and backdoor persistence — review every finding before deleting; it does not replace dedicated antivirus/EDR software."
STR_FR[mw7_warning]="Outil heuristique basé sur des schémas courants de web shells et de persistance de portes dérobées — vérifiez chaque résultat avant suppression ; ne remplace pas un antivirus dédié."
STR_ES[mw7_warning]="Herramienta heurística basada en patrones comunes de web shells y persistencia de puertas traseras — revise cada hallazgo antes de eliminar; no sustituye a un antivirus dedicado."
STR_DE[mw7_warning]="Heuristisches Tool basierend auf gängigen Mustern für Webshells und Backdoor-Persistenz — jeden Fund vor dem Löschen prüfen; ersetzt keine dedizierte Antiviren-Software."
STR_TR[mw7_warning]="Web kabukları ve arka kapı kalıcılığı için yaygın kalıplara dayanan sezgisel bir araçtır — silmeden önce her bulguyu inceleyin; özel bir antivirüs yazılımının yerini tutmaz."
STR_FA[mw7_warning]="ابزاری اکتشافی بر پایه الگوهای رایج وب‌شل و ماندگاری درب‌پشتی — پیش از حذف، هر یافته را بررسی کنید؛ جایگزین آنتی‌ویروس اختصاصی نیست."
STR_RU[mw7_warning]="Эвристический инструмент, основанный на распространённых шаблонах веб-шеллов и закрепления бэкдоров — проверяйте каждую находку перед удалением; не заменяет специализированный антивирус."
STR_KU[mw7_warning]="ئامرازێکی هەستیارە (heuristic) کە پشتی بە شێوازە باوەکانی web shell و مانەوەی دەرگای پشتەوە دەبەستێت — پێش سڕینەوە هەموو دۆزینەوەیەک پێداچوونەوەی بۆ بکە؛ جێگرەوەی نەرمەکاڵای دژە ڤایرۆسی تایبەت نییە."
STR_ZH[mw7_warning]="基于常见 Web Shell 和后门持久化模式的启发式工具——删除前请复核每一项结果；不能替代专用杀毒/EDR软件。"

