STR_AR[hrc_disclaimer]="ملاحظة: هذا فحص سمعة (Hash) مقابل مصادر خارجية محدّثة — يكمّل أدوات الاستدلال بالأداة (heuristics)، وما يعوّض عنها. نتيجة نظيفة هنا ما تعني 100% أن الملف آمن (احتمال zero-day)."
STR_EN[hrc_disclaimer]="Note: this is a hash-reputation lookup against live external feeds — it complements this toolkit's heuristic checks, not a replacement for them. A clean result here does not guarantee the file is 100% safe (zero-day is still possible)."

