STR_AR[mw9_title]="🧬 فحص قواعد YARA-lite (كشف تمويه بالمحتوى)"
STR_EN[mw9_title]="🧬 YARA-lite Rule Scan (content obfuscation detection)"

STR_AR[mw9_disclaimer]="يطابق أنماط بمحتوى الملف نفسه (تجميع نصوص، chr()، hex escapes، صور تحوي PHP...) مب بس التوقيع الحرفي — يمسك نسخاً مموّهة من webshells معروفة. راجع أي نتيجة يدوياً قبل أي إجراء."
STR_EN[mw9_disclaimer]="Matches patterns in the file's own content (string concatenation, chr() building, hex escapes, image-with-PHP polyglots...) not just a literal signature — catches obfuscated variants of known webshells. Always review a result manually before acting on it."

STR_AR[mw9_pcre_unsupported]="ملاحظة: grep -P (PCRE) غير مدعوم بهذا النظام (شائع بأنظمة macOS/BSD أو Alpine الأساسية) — طبقة قواعد YARA-lite متجاوزة هالمرة، والقرار يعتمد فقط على الكاشف الكلاسيكي. لدعم كامل ثبّت GNU grep (بديل: apk add grep، أو على macOS: brew install grep)."
STR_EN[mw9_pcre_unsupported]="Note: grep -P (PCRE) isn't supported on this system (common on macOS/BSD or a minimal Alpine grep) — the YARA-lite rules layer is skipped this run, and the decision relies on the classic detector alone. For full support, install GNU grep (e.g. apk add grep on Alpine, or brew install grep on macOS)."

